CREATE DATABASE shop;

CREATE USER 'shop_app'@'%' IDENTIFIED BY 'change-me-to-something-long';
GRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'shop_app'@'%';

CREATE ROLE 'shop_read';
GRANT SELECT ON shop.* TO 'shop_read';
CREATE USER 'analyst'@'10.0.%' IDENTIFIED BY 'another-long-password';
GRANT 'shop_read' TO 'analyst'@'10.0.%';
SET DEFAULT ROLE ALL TO 'analyst'@'10.0.%';

SHOW GRANTS FOR 'shop_app'@'%';
-- GRANT USAGE ON *.* TO `shop_app`@`%`
-- GRANT SELECT, INSERT, UPDATE, DELETE ON `shop`.* TO `shop_app`@`%`

CREATE TABLE member (
    email    VARCHAR(255) NOT NULL,
    nickname VARCHAR(50) COLLATE utf8mb4_0900_as_cs,
    UNIQUE KEY uk_email (email)
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

INSERT INTO member VALUES ('ana@example.com', 'Ana 🎲');
INSERT INTO member VALUES ('ANA@example.com', 'ana');
-- ERROR 1062 (23000): Duplicate entry 'ANA@example.com' for key 'member.uk_email'

SELECT 'resume' = 'Résumé';                               -- 1 (ai_ci)
SELECT 'resume' = 'Résumé' COLLATE utf8mb4_0900_as_cs;    -- 0
SELECT nickname FROM member WHERE nickname = 'ANA 🎲';     -- empty: column is as_cs

SELECT @@SESSION.sql_mode;
-- ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,...

CREATE TABLE t (n TINYINT, s VARCHAR(3));
INSERT INTO t VALUES (300, 'abcdef');
-- ERROR 1264 (22003): Out of range value for column 'n' at row 1

SET SESSION sql_mode = '';                -- what NOT to do
INSERT INTO t VALUES (300, 'abcdef');     -- Query OK, 1 row affected, 2 warnings
SELECT * FROM t;                          -- 127 | abc   (silently mangled)
SET SESSION sql_mode = DEFAULT;

CREATE TABLE emp (dept VARCHAR(10), name VARCHAR(20));
SELECT dept, name FROM emp GROUP BY dept;
-- ERROR 1055: ... not in GROUP BY clause ... incompatible with sql_mode=only_full_group_by
SELECT dept, ANY_VALUE(name) FROM emp GROUP BY dept;   -- explicit, allowed

CREATE TABLE account (id INT PRIMARY KEY, balance DECIMAL(10,2) NOT NULL);
INSERT INTO account VALUES (1, 100), (2, 50);

START TRANSACTION;
SELECT balance FROM account WHERE id = 1 FOR UPDATE;   -- lock the row we'll change
UPDATE account SET balance = balance - 30 WHERE id = 1;
UPDATE account SET balance = balance + 30 WHERE id = 2;
COMMIT;

START TRANSACTION;
UPDATE account SET balance = 0 WHERE id = 1;
CREATE TABLE audit_log (id INT);    -- implicit COMMIT happens here!
ROLLBACK;                           -- too late: the UPDATE is already committed
SELECT balance FROM account WHERE id = 1;   -- 0.00

SELECT @@transaction_isolation;     -- REPEATABLE-READ

CREATE TABLE product (
    id   INT PRIMARY KEY,
    doc  JSON NOT NULL,
    brand VARCHAR(50) AS (doc->>'$.brand') VIRTUAL,
    KEY idx_brand (brand),
    INDEX idx_tags ((CAST(doc->'$.tags' AS CHAR(20) ARRAY)))
);
INSERT INTO product (id, doc) VALUES
 (1, '{"brand": "Acme", "tags": ["sale", "new"], "sizes": [{"s": "M", "qty": 3}]}'),
 (2, '{"brand": "Zeta", "tags": ["new"], "sizes": [{"s": "L", "qty": 0}]}');

SELECT id, doc->'$.brand', doc->>'$.brand' FROM product WHERE brand = 'Acme';
-- 1 | "Acme" | Acme
SELECT id FROM product WHERE 'sale' MEMBER OF (doc->'$.tags');   -- 1 (uses idx_tags)

SELECT p.id, s.size, s.qty
FROM product p, JSON_TABLE(p.doc, '$.sizes[*]'
     COLUMNS (size VARCHAR(5) PATH '$.s', qty INT PATH '$.qty')) AS s;
-- 1 | M | 3
-- 2 | L | 0
UPDATE product SET doc = JSON_SET(doc, '$.brand', 'Acme Co') WHERE id = 1;

CREATE TABLE seat (id INT PRIMARY KEY, taken BOOL NOT NULL DEFAULT FALSE);
INSERT INTO seat (id) VALUES (10), (20), (30);

-- Session A (REPEATABLE READ)
START TRANSACTION;
SELECT * FROM seat WHERE id BETWEEN 10 AND 20 FOR UPDATE;   -- next-key locks

-- Session B
INSERT INTO seat (id) VALUES (15);     -- waits: gap (10, 20) is locked by A

-- Session C: see who waits for whom
SELECT waiting_pid, waiting_query, blocking_pid, blocking_query
FROM sys.innodb_lock_waits;

-- Session A
COMMIT;                                -- B's insert proceeds

-- job queue: each worker gets a different free seat without waiting
SELECT id FROM seat WHERE NOT taken ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;

CREATE TABLE orders (id BIGINT PRIMARY KEY, customer_id BIGINT, note VARCHAR(100));

SET SESSION lock_wait_timeout = 5;          -- don't queue forever on the MDL

ALTER TABLE orders ADD COLUMN source VARCHAR(20) NULL, ALGORITHM = INSTANT;
-- Query OK, 0 rows affected (0.01 sec)

ALTER TABLE orders ADD INDEX idx_customer (customer_id),
      ALGORITHM = INPLACE, LOCK = NONE;     -- reads and writes continue

ALTER TABLE orders MODIFY note TEXT, ALGORITHM = INPLACE, LOCK = NONE;
-- ERROR 1846 (0A000): ALGORITHM=INPLACE is not supported.
--   Reason: Cannot change column type INPLACE. Try ALGORITHM=COPY.

SELECT object_name, lock_type, lock_status, owner_thread_id
FROM performance_schema.metadata_locks WHERE object_name = 'orders';

CREATE TABLE event (
    id         BIGINT NOT NULL AUTO_INCREMENT,
    created_at DATETIME NOT NULL,
    kind       VARCHAR(20) NOT NULL,
    PRIMARY KEY (id, created_at)          -- must include the partitioning column
)
PARTITION BY RANGE COLUMNS (created_at) (
    PARTITION p2026_04 VALUES LESS THAN ('2026-05-01'),
    PARTITION p2026_05 VALUES LESS THAN ('2026-06-01'),
    PARTITION pmax     VALUES LESS THAN (MAXVALUE)
);
INSERT INTO event (created_at, kind) VALUES ('2026-04-20', 'login'), ('2026-05-02', 'click');

EXPLAIN SELECT COUNT(*) FROM event WHERE created_at >= '2026-05-01' AND created_at < '2026-06-01';
-- partitions: p2026_05

ALTER TABLE event REORGANIZE PARTITION pmax INTO (
    PARTITION p2026_06 VALUES LESS THAN ('2026-07-01'),
    PARTITION pmax     VALUES LESS THAN (MAXVALUE));
ALTER TABLE event DROP PARTITION p2026_04;   -- instant retention

// MySQL Shell (JavaScript mode): mysqlsh clusteradmin@db1
dba.configureInstance('clusteradmin@db1:3306');   // checks GTID, binlog, PKs...
var cluster = dba.createCluster('shop');
cluster.addInstance('clusteradmin@db2:3306', {recoveryMethod: 'clone'});
cluster.addInstance('clusteradmin@db3:3306', {recoveryMethod: 'clone'});
cluster.status();
// "status": "OK", "statusText": "Cluster is ONLINE and can tolerate up to ONE failure."

// on each app host: bootstrap MySQL Router against the cluster
// $ mysqlrouter --bootstrap clusteradmin@db1:3306 --directory /opt/router
// apps connect to the router: 6446 = read/write (primary), 6447 = read-only

ANALYZE TABLE orders UPDATE HISTOGRAM ON status WITH 32 BUCKETS;
SELECT column_name, JSON_EXTRACT(histogram, '$."histogram-type"') AS type
FROM information_schema.column_statistics WHERE table_name = 'orders';
-- status | "singleton"

ALTER TABLE orders STATS_SAMPLE_PAGES = 200;
ANALYZE TABLE orders;                          -- refresh index statistics

SELECT /*+ INDEX(o idx_customer) MAX_EXECUTION_TIME(2000) */ o.id, o.total
FROM orders o
WHERE o.customer_id = 42 AND o.status = 'refunded';

SET optimizer_trace = 'enabled=on';
SELECT id FROM orders WHERE customer_id = 42 AND status = 'refunded';
SELECT JSON_EXTRACT(trace, '$**.considered_access_paths')
FROM information_schema.optimizer_trace;
SET optimizer_trace = 'enabled=off';
